(function initProviderTransferActions() {
  var addButton = $('btnAddProvider');
  var actions = addButton && addButton.parentElement;
  if (!actions || $('btnImportProviders') || $('btnExportProviders')) return;

  function makeTransferButton(id, label, glyph) {
    var button = document.createElement('button');
    button.type = 'button';
    button.id = id;
    button.className = 'section-create-btn';
    button.title = label;
    button.setAttribute('aria-label', label);
    button.textContent = glyph;
    actions.insertBefore(button, addButton);
    return button;
  }

  var importButton = makeTransferButton('btnImportProviders', '导入供应商', '⇩');
  var exportButton = makeTransferButton('btnExportProviders', '导出供应商', '⇧');

  importButton.addEventListener('click', async function(event) {
    event.preventDefault();
    event.stopPropagation();
    importButton.disabled = true;
    try {
      var result = await call('providerImport');
      if (!result || result.cancelled) return;
      if (!result.ok) {
        toast(result.error || '导入失败', 'error');
        return;
      }
      var parts = ['已导入 ' + (result.imported || 0) + ' 个供应商'];
      if (result.skippedExact) parts.push('跳过重复 ' + result.skippedExact + ' 个');
      if (result.skippedConflicts) parts.push('跳过冲突 ' + result.skippedConflicts + ' 个');
      if (result.renamed) parts.push('自动重命名 ' + result.renamed + ' 个');
      toast(parts.join('，'), result.imported ? 'success' : 'info');
      var nextState = await call('getState');
      if (applyPanelState(nextState)) render();
    } finally {
      importButton.disabled = false;
    }
  });

  exportButton.addEventListener('click', async function(event) {
    event.preventDefault();
    event.stopPropagation();
    exportButton.disabled = true;
    try {
      var result = await call('providerExport');
      if (!result || result.cancelled) return;
      if (!result.ok) {
        toast(result.error || '导出失败', 'error');
        return;
      }
      toast('已导出 ' + (result.count || 0) + ' 个供应商' + (result.includesKeys ? '（包含 Key）' : '（不含 Key）'), result.includesKeys ? 'warning' : 'success');
    } finally {
      exportButton.disabled = false;
    }
  });
})();

bootstrapPanel();
