(function initNativeSubagentActions() {
  var status = $('nativeSubagentStatus');
  var picker = $('nativeSubagentPicker');
  var provider = $('nativeSubagentProvider');
  var model = $('nativeSubagentModel');
  var modelLabel = $('nativeSubagentModelLabel');
  var save = $('btnSaveSubagentRoute');
  var choose = $('btnConfigureSubagentRoute');
  if (!status || !picker || !provider || !model || !modelLabel || !save || !choose) return;
  var choices = [];
  var currentRoute = { mode: 'native', modelUid: '' };
  function addOption(select, value, label) {
    var option = document.createElement('option');
    option.value = value;
    option.textContent = label;
    select.appendChild(option);
  }
  function renderModels(selectedUid) {
    var providerId = provider.value;
    model.replaceChildren();
    modelLabel.hidden = !providerId;
    if (!providerId) { save.disabled = false; return; }
    addOption(model, '', '请选择模型');
    choices.filter(function(item) { return item.providerId === providerId; }).forEach(function(item) {
      addOption(model, item.modelUid, item.modelId + ' · ' + item.modelUid);
    });
    model.value = selectedUid || '';
    save.disabled = !model.value;
  }
  function renderProviders() {
    var selected = choices.find(function(item) { return item.modelUid === currentRoute.modelUid; });
    var names = new Map();
    choices.forEach(function(item) { names.set(item.providerId, item.providerName || item.providerId); });
    provider.replaceChildren();
    addOption(provider, '', 'Devin 原生模型');
    Array.from(names).sort(function(a, b) { return a[1].localeCompare(b[1]); }).forEach(function(item) {
      addOption(provider, item[0], item[1]);
    });
    provider.value = selected ? selected.providerId : '';
    renderModels(selected ? selected.modelUid : '');
  }
  async function refreshStatus() {
    var result = await call('nativeSubagentStatus');
    if (!result || !result.ok) {
      status.textContent = '子代理状态读取失败';
      return false;
    }
    var profiles = result.profiles || {};
    var profileText = profiles.installed ? '配置已安装' : '配置未安装';
    if ((profiles.profiles || []).some(function(item) { return item.status === 'modified'; })) profileText = '发现同名配置差异';
    var routeText = result.routeError ? '模型路由配置无效' : result.route && result.route.mode === 'bound'
      ? '模型：' + result.route.modelUid : '模型：Devin 原生';
    status.textContent = profileText + ' · ' + routeText;
    choices = Array.isArray(result.choices) ? result.choices : [];
    currentRoute = result.route || { mode: 'native', modelUid: '' };
    return true;
  }
  function bindAction(id, command, successText) {
    var button = $(id);
    if (!button) return;
    button.addEventListener('click', async function(event) {
      event.preventDefault();
      event.stopPropagation();
      button.disabled = true;
      try {
        var result = await call(command);
        if (result && result.cancelled) return;
        if (!result || !result.ok) toast(result && result.error || '操作失败', 'error');
        else toast(successText, 'success');
        await refreshStatus();
      } finally {
        button.disabled = false;
      }
    });
  }
  bindAction('btnInstallNativeSubagents', 'nativeSubagentInstall', '原生子代理配置已安装');
  bindAction('btnRemoveNativeSubagents', 'nativeSubagentRemove', '原生子代理配置已移除');
  choose.setAttribute('aria-expanded', 'false');
  choose.addEventListener('click', async function(event) {
    event.preventDefault();
    event.stopPropagation();
    if (!picker.hidden) { picker.hidden = true; choose.setAttribute('aria-expanded', 'false'); return; }
    choose.disabled = true;
    try {
      if (!await refreshStatus()) { toast('子代理模型列表读取失败', 'error'); return; }
      renderProviders();
      picker.hidden = false;
      choose.setAttribute('aria-expanded', 'true');
      provider.focus();
    } finally { choose.disabled = false; }
  });
  provider.addEventListener('change', function() { renderModels(''); });
  model.addEventListener('change', function() { save.disabled = !!provider.value && !model.value; });
  $('btnCancelSubagentRoute').addEventListener('click', function() {
    picker.hidden = true;
    choose.setAttribute('aria-expanded', 'false');
  });
  save.addEventListener('click', async function() {
    var mode = provider.value ? 'bound' : 'native';
    if (mode === 'bound' && !model.value) return;
    save.disabled = true;
    try {
      var result = await call('nativeSubagentSaveRoute', { mode: mode, modelUid: model.value });
      if (!result || !result.ok) { toast(result && result.error || '保存失败', 'error'); return; }
      toast('子代理模型路由已更新', 'success');
      picker.hidden = true;
      choose.setAttribute('aria-expanded', 'false');
      await refreshStatus();
    } finally { save.disabled = !!provider.value && !model.value; }
  });
  refreshStatus();
})();

(function initNativeMcpTools() {
  var list = $('nativeMcpList');
  if (!list) return;
  async function refresh() {
    var result = await call('nativeMcpStatus');
    list.replaceChildren();
    if (!result || !result.ok) {
      var error = document.createElement('div');
      error.className = 'hint';
      error.textContent = result && result.error || 'MCP 工具状态读取失败';
      list.appendChild(error);
      return;
    }
    (result.items || []).forEach(function(item) {
      var row = document.createElement('label');
      row.className = 'native-mcp-row';
      var copy = document.createElement('span');
      copy.className = 'native-mcp-copy';
      var title = document.createElement('strong');
      title.textContent = item.label;
      var detail = document.createElement('small');
      detail.textContent = item.conflict ? '存在同名配置冲突' : item.kind === 'remote'
        ? (item.enabled ? '已开启 · 远程连接' : '已关闭 · 开启后直接连接')
        : item.enabled
          ? (item.external ? '已开启 · 使用已有配置' : '已开启 · 已安装 v' + item.version)
          : (item.installed ? '已关闭 · 已安装 v' + item.version : '已关闭 · 首次开启时安装');
      copy.append(title, detail);
      var toggle = document.createElement('input');
      toggle.type = 'checkbox';
      toggle.setAttribute('role', 'switch');
      toggle.setAttribute('aria-label', item.label);
      toggle.checked = !!item.enabled;
      toggle.disabled = !!item.conflict;
      toggle.addEventListener('change', async function() {
        toggle.disabled = true;
        detail.textContent = toggle.checked ? (item.kind === 'remote' ? '正在连接…' : '正在安装并启用…') : '正在关闭…';
        var updated = await call('nativeMcpToggle', { name: item.name, enabled: toggle.checked, timeoutMs: item.name === 'blender' ? 300000 : 180000 });
        if (!updated || !updated.ok) toast(updated && updated.error || 'MCP 工具切换失败', 'error');
        else toast(toggle.checked ? 'MCP 已开启；请新建 Devin 会话' : 'MCP 已关闭；新会话不再加载', 'success');
        await refresh();
      });
      row.append(copy, toggle);
      list.appendChild(row);
    });
  }
  refresh();
})();

bootstrapPanel();
